-- ================================================================
-- BoothIQ Seed Script  (run AFTER schema.sql)
-- ================================================================
--
-- HOW TO USE WITH YOUR 500-RECORD DATASET:
--
--   1. Open your voter dataset file (MySQL dump).
--   2. Find & Replace ALL occurrences of:
--          `tableName`   →   voter_staging
--      (remove the backticks, use plain text: voter_staging)
--   3. Paste all the resulting INSERT statements into the
--      "PASTE YOUR DATA HERE" section below (Step 2).
--   4. Run this entire script in Supabase → SQL Editor.
--
-- SEGMENT MAPPING (auto-handled by this script):
--   trader     → businessman
--   daily_wage → other
--   All other values (farmer, youth, women, senior, etc.) pass through.
--
-- ================================================================

BEGIN;

-- ─────────────────────────────────────────────────────────────────
-- STEP 1: STAGING TABLE
-- Mirrors the MySQL export schema exactly.
-- ─────────────────────────────────────────────────────────────────

CREATE TEMP TABLE voter_staging (
    id                  VARCHAR(512),
    epic_number         VARCHAR(512),
    name                VARCHAR(512),
    dob                 VARCHAR(512),
    age                 INT,
    gender              VARCHAR(512),
    phone               VARCHAR(512),   -- keep as text; source has INT but may start with 6/7/8/9
    address             VARCHAR(512),
    street              VARCHAR(512),
    booth_id            VARCHAR(512),   -- 'b001', 'b002', etc.
    booth_number        INT,
    segment             VARCHAR(512),
    occupation          VARCHAR(512),
    education           VARCHAR(512),
    family_size         INT,
    is_key_voter        VARCHAR(512),   -- 'True' / 'False' string
    network_size        VARCHAR(512),
    aadhaar_verified    VARCHAR(512),   -- 'True' / 'False' string
    preferred_language  VARCHAR(512),
    scheme_gap_count    VARCHAR(512)
);


-- ─────────────────────────────────────────────────────────────────
-- STEP 2: PASTE YOUR DATA HERE
--
-- Replace `tableName` with voter_staging in your INSERT statements,
-- then paste all 500 rows below this comment.
-- ─────────────────────────────────────────────────────────────────

-- INSERT INTO voter_staging (id, epic_number, name, dob, age, gender, phone, address, street, booth_id, booth_number, segment, occupation, education, family_size, is_key_voter, network_size, aadhaar_verified, preferred_language, scheme_gap_count) VALUES (...);
-- (paste all rows here)




-- ─────────────────────────────────────────────────────────────────
-- STEP 3: GEOGRAPHY HIERARCHY
-- Uses plain integer IDs (BIGINT GENERATED BY DEFAULT AS IDENTITY).
-- ─────────────────────────────────────────────────────────────────

-- State: Uttar Pradesh
VALUES (1, 'Uttar Pradesh', 'UP')
ON CONFLICT (id) DO NOTHING;

-- District: Varanasi
VALUES (1, 1, 'Varanasi', 'VNS')
ON CONFLICT (id) DO NOTHING;

-- Constituency: Varanasi North (Vidhan Sabha)
VALUES (1, 1, 'Varanasi North', 'vidhan_sabha', 'UP/65')
ON CONFLICT (id) DO NOTHING;

-- Booths — derive distinct booths from staging data
SELECT DISTINCT
    1,
    s.booth_number::VARCHAR,
    'Booth ' || s.booth_number || ' - ' || MIN(SPLIT_PART(s.address, ', ', 3)),
    MIN(SPLIT_PART(s.address, ', ', 3)) || ', Varanasi'
FROM voter_staging s
GROUP BY s.booth_number
ON CONFLICT DO NOTHING;

-- Streets — derive distinct street + booth combinations
SELECT
    b.id,
    s.street,
    COUNT(*)
FROM voter_staging s
JOIN booths b ON b.booth_number = s.booth_number::VARCHAR
GROUP BY b.id, s.street
ON CONFLICT DO NOTHING;


-- ─────────────────────────────────────────────────────────────────
-- STEP 4: voters_eci  (ECI source-of-truth, READ ONLY layer)
-- ─────────────────────────────────────────────────────────────────

SELECT
    s.id::BIGINT,
    s.epic_number,
    s.name,
    s.dob::DATE,
    CASE s.gender
        WHEN 'M' THEN 'M'::gender_type
        WHEN 'F' THEN 'F'::gender_type
        ELSE          'O'::gender_type
    END,
    s.phone,
    s.address,
    b.id
FROM voter_staging s
JOIN booths b ON b.booth_number = s.booth_number::VARCHAR
ON CONFLICT (epic_number) DO NOTHING;


-- ─────────────────────────────────────────────────────────────────
-- STEP 5: voters  (operational layer — AI segmentation + preferences)
-- ─────────────────────────────────────────────────────────────────

    id,
    eci_voter_id,
    segment,
    occupation,
    education,
    family_size,
    is_key_voter,
    notif_sms,
    notif_whatsapp,
    notif_push,
    aadhaar_verified,
    preferred_language,
    citizen_portal_active
)
SELECT
    s.id::BIGINT,
    ve.id,
    CASE s.segment
        WHEN 'trader'     THEN 'businessman'::voter_segment
        WHEN 'daily_wage' THEN 'other'::voter_segment
        ELSE s.segment::voter_segment
    END,
    s.occupation,
    s.education,
    s.family_size,
    (s.is_key_voter = 'True'),
    true,   -- notif_sms
    false,  -- notif_whatsapp
    false,  -- notif_push
    (s.aadhaar_verified = 'True'),
    s.preferred_language,
    false   -- citizen_portal_active (one voter flagged below for demo)
FROM voter_staging s
JOIN voters_eci ve ON ve.epic_number = s.epic_number
ON CONFLICT (eci_voter_id) DO NOTHING;


-- ─────────────────────────────────────────────────────────────────
-- STEP 6: SCHEMES  (government welfare catalogue)
-- ─────────────────────────────────────────────────────────────────

                     benefit_amount, icon, program, active)
VALUES
    (1, 'PM-KISAN', 'Ministry of Agriculture & Farmers Welfare', 'Direct income support of ₹6,000 per year to farmer families in three equal installments.', '{"segment": "farmer", "land_ownership": "required"}', '₹6,000/year (3 installments of ₹2,000)', 'agriculture', 'Pradhan Mantri Kisan Samman Nidhi', true),
    (2, 'PM Awas Yojana (Gramin)', 'Ministry of Rural Development', 'Financial assistance for construction of pucca houses to BPL families in rural areas.', '{"income": "BPL", "no_pucca_house": true, "rural": true}', 'Up to ₹1.2 Lakh (plain) / ₹1.3 Lakh (hilly)', 'home', 'PM Awas Yojana Gramin', true),
    (3, 'Ujjwala Yojana 2.0', 'Ministry of Petroleum & Natural Gas', 'Free LPG connection with first refill and hotplate to BPL women households.', '{"gender": ["F", "O"], "bpl": true, "age_min": 18}', 'Free LPG connection + 1 free refill', 'local_fire_department', 'Pradhan Mantri Ujjwala Yojana', true),
    (4, 'Pradhan Mantri Fasal Bima Yojana', 'Ministry of Agriculture & Farmers Welfare', 'Comprehensive crop insurance at nominal premium to protect farmers from crop losses.', '{"segment": "farmer", "cultivating_land": true}', 'Claim based on crop loss assessment', 'shield', 'PMFBY', true),
    (5, 'Atal Pension Yojana', 'Ministry of Finance', 'Guaranteed pension of ₹1,000–₹5,000/month for workers in unorganised sector.', '{"age_min": 18, "age_max": 40, "bank_account": true, "not_income_tax_payer": true}', '₹1,000–₹5,000/month after age 60', 'savings', 'APY', true),
    (6, 'PM Jan Dhan Yojana', 'Ministry of Finance', 'Zero-balance bank account with RuPay debit card, accidental insurance and overdraft facility.', '{"age_min": 10}', 'Zero-balance account + RuPay card + ₹2 Lakh insurance', 'account_balance', 'PMJDY', true),
    (7, 'Beti Bachao Beti Padhao', 'Ministry of Women & Child Development', 'Scheme to promote the welfare, education and survival of the girl child.', '{"gender": ["F"], "age_max": 18}', 'Educational support + welfare benefits', 'school', 'BBBP', true),
    (8, 'PM MUDRA Yojana', 'Ministry of Finance', 'Collateral-free loans under Shishu/Kishore/Tarun categories for micro-entrepreneurs.', '{"segment": ["businessman", "other"], "non_farm": true}', 'Loans from ₹50,000 up to ₹10 Lakh', 'storefront', 'PMMY', true),
    (9, 'PM Vaya Vandana Yojana', 'Ministry of Finance', 'Pension scheme for senior citizens ensuring 7.4% annual return.', '{"age_min": 60}', 'Pension up to ₹9,250/month', 'elderly_care', 'PMVVY', true),
    (10, 'PM Matru Vandana Yojana', 'Ministry of Women & Child Development', 'Cash incentive of ₹5,000 in three installments for pregnant and lactating women.', '{"gender": ["F", "O"], "pregnant_or_lactating": true}', '₹5,000 in 3 installments', 'pregnant_woman', 'PMMVY', true)
ON CONFLICT (id) DO NOTHING;


-- PM-KISAN → all farmers
SELECT v.id, 1, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'farmer'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PMFBY (crop insurance) → farmers
SELECT v.id, 4, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'farmer'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- Ujjwala Yojana → women segment
SELECT v.id, 3, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'women'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- BBBP → women segment
SELECT v.id, 7, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'women'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PMMVY → women segment
SELECT v.id, 10, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'women'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- MUDRA → businessmen
SELECT v.id, 8, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'businessman'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- APY → senior citizens
SELECT v.id, 5,
       'enrolled'::scheme_voter_status, now() - interval '8 months', true, true
FROM voters v
WHERE v.segment = 'senior'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PMVVY → senior citizens
SELECT v.id, 9, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'senior'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PM Jan Dhan → everyone (first 300 enrolled, rest eligible)
SELECT
    v.id,
    6,
    CASE WHEN ROW_NUMBER() OVER (ORDER BY v.created_at) <= 300 THEN 'enrolled'::scheme_voter_status ELSE 'eligible'::scheme_voter_status END,
    CASE WHEN ROW_NUMBER() OVER (ORDER BY v.created_at) <= 300 THEN now() - interval '1 year' ELSE NULL END,
    true,
    CASE WHEN ROW_NUMBER() OVER (ORDER BY v.created_at) <= 300 THEN true ELSE false END
FROM voters v
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PM Awas → key voters + large families as applied
SELECT v.id, 2, 'applied'::scheme_voter_status, true
FROM voters v
WHERE v.is_key_voter = true OR v.family_size >= 6
ON CONFLICT (voter_id, scheme_id) DO NOTHING;


