    (3, 1, 'Hanuman Nagar LED Streetlights', 'electricity', 'Installation of 48 LED streetlights across all 8 lanes of Hanuman Nagar colony.', 'planned'::project_status, 'lightbulb', 'bg-yellow-100', 0, 34, 3, 42),
