    (5, 1, 'Sarnath Heritage Road Beautification', 'road', 'Widening and landscaping of 0.8 km road from Deer Park to Dharmarajika Colony.', 'in_progress'::project_status, 'construction', 'bg-orange-100', 40, 67, 11, 43),
