ON CONFLICT (id) DO NOTHING;


-- ── Demo voter: activate citizen portal for the fixed ID used in the app ──────
UPDATE voters
SET citizen_portal_active = true,
    notif_push            = true
WHERE id = 1;

-- STEP 9: CITIZEN NOTIFICATIONS
SELECT 1, 'PM-KISAN: ₹2,000 Credited', 'Your 16th installment has been credited.', 'payments', false, now() - interval '2 hours'
